import csv
import json

input_path = '/root/trivy_report.json'
output_path = '/root/security_audit.csv'
headers = ['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url']
cvss_sources = ('nvd', 'ghsa', 'redhat')

def text_or_na(value):
    if value is None:
        return 'N/A'
    value = str(value).strip()
    return value if value else 'N/A'

def first_reference(vulnerability):
    references = vulnerability.get('References')
    if isinstance(references, list):
        for reference in references:
            if reference:
                return text_or_na(reference)
    return 'N/A'

def cvss_score(vulnerability):
    cvss = vulnerability.get('CVSS')
    if not isinstance(cvss, dict):
        return 'N/A'
    entries = []
    for source in cvss_sources:
        entry = cvss.get(source)
        if isinstance(entry, dict):
            entries.append(entry)
    for entry in entries:
        for key in ('V3Score', 'V3.1Score', 'V2Score'):
            score = entry.get(key)
            if isinstance(score, (int, float)) and not isinstance(score, bool):
                return str(score)
    for entry in cvss.values():
        if isinstance(entry, dict):
            for key in ('V3Score', 'V3.1Score', 'V2Score'):
                score = entry.get(key)
                if isinstance(score, (int, float)) and not isinstance(score, bool):
                    return str(score)
    return 'N/A'

with open(input_path, encoding='utf-8') as handle:
    report = json.load(handle)

