            'Version': text_or_na(vulnerability.get('InstalledVersion')),
            'CVE_ID': text_or_na(vulnerability.get('VulnerabilityID')),
            'Severity': severity,
            'CVSS_Score': cvss_score(vulnerability),
            'Fixed_Version': text_or_na(vulnerability.get('FixedVersion')),
            'Title': title,
            'Url': text_or_na(vulnerability.get('PrimaryURL')),
        }
        if record['Url'] == 'N/A':
            record['Url'] = first_reference(vulnerability)
        dedupe_key = tuple(record[field] for field in ('Package', 'Version', 'CVE_ID', 'Severity', 'Fixed_Version', 'Url'))
        records[dedupe_key] = record

rows = sorted(records.values(), key=lambda row: (row['Package'], row['Version'], row['CVE_ID'], row['Severity']))
with open(output_path, 'w', newline='', encoding='utf-8') as handle:
    writer = csv.DictWriter(handle, fieldnames=headers)
    writer.writeheader()
    writer.writerows(rows)

print(f'wrote {len(rows)} rows to {output_path}')
